#include <iostream>
#include <sstream>
#include <string>
using namespace std;

class StringBuilder {
    ostringstream oss;
public:
    void append(const string& s) { oss << s; }
    string str() { return oss.str(); }
};

int main() {
    StringBuilder sb;
    sb.append("Hello");
    sb.append(" ");
    sb.append("World");
    cout << sb.str() << endl;
    return 0;
}
